// Generated by website-to-tools from __TITLE__. Streamable HTTP MCP server (stateless, JSON responses).
// Each tool forwards to the site's own API. Read tools are marked read-only. Write tools need confirm=true, which
// the agent may only set after the user said yes. Every call that is not a GET is rate-limited per caller and tool;
// calls the site refused (429, 5xx) do not count. Use as a Vercel/Node function (export default handler) or run
// standalone: node serve.mjs. The caller IP comes from x-real-ip, which only a trusted proxy (Vercel, nginx) may set.
// Optional: FORWARD_SECRET (env) adds X-Forwarded-Client-IP plus an HMAC X-Forward-Signature so the site can trust
// the real caller IP instead of this server's.
import { createHmac } from "node:crypto";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";

const ORIGIN = __ORIGIN__;
const TOOLS = __TOOLS__;
const TAG = __TAG__;
const LIMIT = { max: 3, windowMs: 60 * 60 * 1000 };
const MAX_BATCH = 5;
const hits = new Map(); // "tool|caller" -> timestamps of counted calls

function callerOf(req) {
  return String(req.headers["x-real-ip"] || req.headers["x-forwarded-for"] || req.socket?.remoteAddress || "unknown")
    .split(",")[0].trim();
}

function clientOf(req) {
  return String(req.headers["user-agent"] || "unknown").replace(/[^A-Za-z0-9._/ -]/g, "").slice(0, 60);
}

function recentHits(key) {
  const now = Date.now();
  const recent = (hits.get(key) || []).filter((t) => now - t < LIMIT.windowMs);
  if (recent.length) hits.set(key, recent);
  else hits.delete(key); // keep the map small on long-lived instances
  return recent;
}

function limited(key) {
  return recentHits(key).length >= LIMIT.max;
}

function count(key) {
  hits.set(key, [...recentHits(key), Date.now()]);
}

function forwardHeaders(caller) {
  const secret = process.env.FORWARD_SECRET;
  if (!secret) return {};
  const sig = createHmac("sha256", secret).update(caller).digest("hex");
  return { "X-Forwarded-Client-IP": caller, "X-Forward-Signature": sig };
}

function listed(tool) {
  const properties = Object.fromEntries(tool.params.map((p) => [p.name, {
    type: p.type, description: p.description, ...(p.enum ? { enum: p.enum } : {}),
  }]));
  const required = tool.params.filter((p) => p.required).map((p) => p.name);
  if (tool.kind === "write") {
    properties.confirm = { type: "boolean", description: "Set true ONLY after showing the user exactly what will be sent and the user explicitly said yes. Leave it out to get a preview." };
  }
  return {
    name: tool.name, title: tool.summary, description: tool.description,
    inputSchema: { type: "object", properties, required },
    annotations: { readOnlyHint: tool.kind === "read", destructiveHint: false, openWorldHint: true },
  };
}

function buildRequest(tool, args, client) {
  let path = tool.path;
  const query = new URLSearchParams();
  const body = {};
  for (const p of tool.params) {
    const value = args[p.name];
    if (value === undefined || value === null || value === "") continue;
    if (p.in === "path") path = path.replace(`{${p.name}}`, encodeURIComponent(String(value)));
    else if (p.in === "query") query.set(p.name, String(value));
    else body[p.name] = value;
  }
  for (const [k, v] of Object.entries(TAG.query || {})) query.set(k, v.replace("{client}", client));
  for (const [k, v] of Object.entries(TAG.body || {})) if (tool.method !== "GET") body[k] = v.replace("{client}", client);
  const qs = query.toString();
  return { url: ORIGIN + path + (qs ? "?" + qs : ""), body: tool.method === "GET" ? undefined : JSON.stringify(body) };
}

async function callTool(tool, args, ctx) {
  const missing = tool.params.filter((p) => p.required && String(args[p.name] ?? "").trim() === "");
  if (missing.length) return text(`Missing: ${missing.map((p) => p.name).join(", ")}.`, true);
  if (tool.kind === "write" && args.confirm !== true) {
    const preview = Object.fromEntries(tool.params.filter((p) => args[p.name] !== undefined).map((p) => [p.name, args[p.name]]));
    return text(`Not sent yet. Show the user exactly this and ask them to confirm, then call again with confirm=true:\n${JSON.stringify(preview, null, 2)}`);
  }
  const key = `${tool.name}|${ctx.caller}`;
  if (tool.method !== "GET" && limited(key)) return text("Too many requests from you in the last hour. Please try later.", true);
  const { url, body } = buildRequest(tool, args, ctx.client);
  console.info(JSON.stringify({ event: "mcp_tool", tool: tool.name, kind: tool.kind, client: ctx.client, src: "mcp" }));
  const headers = { Accept: "application/json", "X-Source": "mcp", ...forwardHeaders(ctx.caller),
    ...(body ? { "Content-Type": "application/json" } : {}) };
  try {
    const res = await fetch(url, { method: tool.method, headers, body });
    if (tool.method !== "GET" && res.status !== 429 && res.status < 500) count(key);
    const out = await res.text();
    return text(out.slice(0, 50000), !res.ok);
  } catch (err) {
    console.error(JSON.stringify({ event: "mcp_tool_failed", tool: tool.name, reason: err?.message }));
    return text("The site could not be reached. Please try again shortly.", true);
  }
}

function text(value, isError = false) {
  return { content: [{ type: "text", text: value }], isError };
}

function makeServer(ctx) {
  const server = new Server({ name: __NAME__, version: __VERSION__ }, { capabilities: { tools: {} }, instructions: __INSTRUCTIONS__ });
  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: TOOLS.map(listed) }));
  server.setRequestHandler(CallToolRequestSchema, async (req) => {
    const tool = TOOLS.find((t) => t.name === req.params.name);
    if (!tool) return text(`Unknown tool ${req.params.name}.`, true);
    return callTool(tool, req.params.arguments || {}, ctx);
  });
  return server;
}

export default async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "content-type, mcp-protocol-version, mcp-session-id, accept");
  res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
  if (req.method === "OPTIONS") return res.status ? res.status(204).end() : (res.writeHead(204), res.end());
  if (req.method !== "POST") {
    res.writeHead(405, { "Content-Type": "application/json", Allow: "POST" });
    return res.end(JSON.stringify({ jsonrpc: "2.0", error: { code: -32000, message: "Use POST (streamable HTTP, stateless)." }, id: null }));
  }
  if (Array.isArray(req.body) && req.body.length > MAX_BATCH) {
    res.writeHead(400, { "Content-Type": "application/json" });
    return res.end(JSON.stringify({ jsonrpc: "2.0", error: { code: -32600, message: `At most ${MAX_BATCH} messages per batch.` }, id: null }));
  }
  const server = makeServer({ caller: callerOf(req), client: clientOf(req) });
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined, enableJsonResponse: true });
  res.on("close", () => { transport.close(); server.close(); });
  try {
    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } catch (err) {
    console.error(JSON.stringify({ event: "mcp_failed", reason: err?.message }));
    if (!res.headersSent) {
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ jsonrpc: "2.0", error: { code: -32603, message: "Internal error" }, id: null }));
    }
  }
}
